CREATE OR REPLACE FUNCTION public.tg_validate_document_approval() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.status='aprovado' AND OLD.status<>'aprovado' AND NEW.tipo_documento<>'canhoto' THEN RAISE EXCEPTION 'Somente canhoto validado pode aprovar entrega'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_document_approval BEFORE UPDATE OF status ON public.comprovantes FOR EACH ROW EXECUTE FUNCTION public.tg_validate_document_approval();
CREATE POLICY finance_loads_read ON public.cargas FOR SELECT TO authenticated USING(private.can_finance(auth.uid()));
CREATE POLICY receive_loads_update ON public.cargas_entrada FOR UPDATE TO authenticated USING(private.can_receive(auth.uid())) WITH CHECK(private.can_receive(auth.uid()));
CREATE POLICY receive_notes_update ON public.notas_fiscais FOR UPDATE TO authenticated USING(private.can_receive(auth.uid())) WITH CHECK(private.can_receive(auth.uid()));
CREATE POLICY receive_documents_read ON public.documentos_recebimento FOR SELECT TO authenticated USING(private.can_receive(auth.uid()));
CREATE POLICY receive_documents_insert ON public.documentos_recebimento FOR INSERT TO authenticated WITH CHECK(private.can_receive(auth.uid()));
CREATE POLICY receive_occurrences_read ON public.ocorrencias FOR SELECT TO authenticated USING(private.can_receive(auth.uid()));
CREATE POLICY receive_suppliers_read ON public.fornecedores FOR SELECT TO authenticated USING(private.can_receive(auth.uid()));
CREATE POLICY active_driver_object_read ON storage.objects AS RESTRICTIVE FOR SELECT TO authenticated USING(bucket_id<>'comprovantes' OR private.active_user(auth.uid()));
CREATE OR REPLACE FUNCTION public.tg_recebimento_documento_identidade() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE nome text;kg numeric;tarifa numeric; BEGIN IF auth.uid() IS NULL OR NOT private.can_receive(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão para salvar documentos'; END IF; SELECT coalesce(nullif(p.nome,''),p.email) INTO nome FROM public.profiles p WHERE p.id=auth.uid(); PERFORM 1 FROM public.cargas_entrada WHERE id=NEW.carga_entrada_id FOR UPDATE; NEW.registrado_por:=auth.uid();NEW.registrado_por_nome:=nome; IF TG_TABLE_NAME='checklists_recebimento' THEN IF TG_OP='UPDATE' THEN IF NEW.carga_entrada_id IS DISTINCT FROM OLD.carga_entrada_id THEN RAISE EXCEPTION 'O vínculo da conferência não pode mudar'; END IF;NEW.versao:=OLD.versao+1;NEW.created_at:=OLD.created_at;ELSE NEW.versao:=1;END IF;NEW.updated_at:=now(); ELSE SELECT coalesce(max(versao),0)+1 INTO NEW.versao FROM public.documentos_recebimento WHERE carga_entrada_id=NEW.carga_entrada_id AND tipo=NEW.tipo;NEW.created_at:=now();IF NEW.tipo='recibo' THEN kg:=(NEW.dados->>'peso_kg')::numeric;tarifa:=(NEW.dados->>'tarifa')::numeric;IF kg IS NULL OR tarifa IS NULL OR kg<0 OR tarifa<0 THEN RAISE EXCEPTION 'Peso e tarifa inválidos';END IF;NEW.dados:=NEW.dados||jsonb_build_object('toneladas',kg/1000,'valor_total',round(kg/1000*tarifa,2));END IF;END IF;RETURN NEW;END $$;
CREATE OR REPLACE FUNCTION public.reverter_aprovacao(_id uuid,_motivo text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c comprovantes; BEGIN IF NOT private.has_role(auth.uid(),'administrador') OR length(trim(_motivo))<3 THEN RAISE EXCEPTION 'Reversão exige administrador e justificativa'; END IF; SELECT * INTO c FROM comprovantes WHERE id=_id FOR UPDATE; IF c.status<>'aprovado' THEN RAISE EXCEPTION 'Comprovante não aprovado'; END IF; IF EXISTS(SELECT 1 FROM financeiro WHERE nota_fiscal_id=c.nota_id AND estado_frete IN ('conferido','pronto_faturamento','faturado')) THEN RAISE EXCEPTION 'Financeiro fechado: revisão manual necessária'; END IF; UPDATE comprovantes SET status='rejeitado',motivo_rejeicao=_motivo WHERE id=_id; UPDATE entregas SET resultado='nao_entregue',motivo=_motivo WHERE id=c.entrega_id; UPDATE notas_fiscais SET status='nao_entregue' WHERE id=c.nota_id; UPDATE financeiro SET estado_frete='aprovacao_revertida' WHERE nota_fiscal_id=c.nota_id; INSERT INTO historico(entidade,entidade_id,acao,descricao,user_id) VALUES('comprovante',_id,'aprovacao_revertida',_motivo,auth.uid()); END $$;
REVOKE ALL ON FUNCTION public.reverter_aprovacao(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.reverter_aprovacao(uuid,text) TO authenticated;
